mut('D159', DOC, 'if [[ -z "$_wtd" && -n "$_adopted" ]]; then', 'if [[ -z "$_wtd" ]]; then', 'flight-rules-doctor', what='doctor: a repository that never adopted flight-rules is told where its worktrees go, every day (V17)')
mut('D160', DOC, '[[ -n "${HOOKS_DIR:-}" ]] && grep -q "$(hook_marker pre-merge-commit)" "$HOOKS_DIR/pre-merge-commit" 2>/dev/null && _adopted=1', ':', 'flight-rules-doctor', what='doctor: a project with no conf, on its hooks, is not told where its worktrees go (V17)')
mut('D161', DOC, 'if [[ -z "$_wtd" && -n "$_adopted" ]]; then', 'if [[ -z "$(grep -E \'^[[:space:]]*WORKTREE_DIR[[:space:]]*=\' "$CONF" 2>/dev/null)" && -n "$_adopted" ]]; then', 'flight-rules-doctor', what='doctor: WORKTREE_DIR= set empty silences the notice (V17)')
mut('T89', RT, '    elif [ -e "$(git_path MERGE_HEAD)" ]; then echo "git commit --no-edit"\n', '', 'ref-gate', what='ref gate: a refused merge is printed the same command, which fails on the unfinished merge (V12)')


def _check_data():
    seen = set()
    for m in M:
        assert m['id'] not in seen, 'duplicate id ' + m['id']
        seen.add(m['id'])
        assert m['old'] and m['old'] != m['new'], m['id'] + ': old must be non-empty and differ from new'
        assert m['suites'] and all(s in SUITES for s in m['suites']), m['id'] + ': unknown suite'
        assert m['expect'] == 'killed' or m['expect'].startswith('survives: '), m['id'] + ': bad expect'
        assert m['id'] != 'control', 'control is run.sh\'s control, not a mutant id'


def _read(p):
    with open(p, encoding='utf-8', newline='') as f:
        return f.read()


STAMP_HEAD = 'flight-rules mutation stamp'
# The results run.sh writes in a stamp's rows, and no others: read by prefix, any
# 'killed…' passed as a kill (0.29.0 release review, second pass, V4).
RESULTS = ('killed', 'killed-abort', 'killed-timeout', 'survived')


def verify(sha, path, by_id):
    """The release review check: the stamp at <path> is a clean whole-kit run of <sha>."""
    lines = _read(path).splitlines()
    bad = []
    if not lines or lines[0] != STAMP_HEAD:
        bad.append("its first line is not '%s': not a stamp run.sh wrote" % STAMP_HEAD)
    summary = lines[1] if len(lines) > 1 else ''
    if not summary.startswith('mutation: all '):
        bad.append('its summary is not of the whole kit: %r' % summary)
    if (' run from %s — ' % sha) not in summary:
        bad.append('its summary is not of %s with no tracked file changed: %r' % (sha, summary))
    if not summary.endswith(', 0 failed to apply; 0 unexpected survivor(s)'):
        bad.append('its summary is not clean: %r' % summary)
    seen, stale, unsure = {}, [], []
    for row in lines[2:]:
        f = row.split('\t')
        if len(f) != 3:
            bad.append('a row is not <id> <result> <suite>: %r' % row); continue
        seen[f[0]] = seen.get(f[0], 0) + 1
        m = by_id.get(f[0])
        if m is None:
            bad.append('%s is not a mutant at this commit' % f[0]); continue
        if f[1] not in RESULTS:
            bad.append('%s: %r is not a result run.sh writes' % (f[0], f[1])); continue
        if m['expect'] == 'killed':
            if f[1] == 'survived':
                bad.append('%s: %s, expected killed' % (f[0], f[1]))
        elif f[1] == 'killed':
            stale.append(f[0])
        elif f[1] in ('killed-abort', 'killed-timeout'):
            unsure.append('%s %s' % (f[0], f[1]))
    bad += ['%s: %d rows' % (i, n) for i, n in seen.items() if n > 1]
    bad += ['%s: no row — the run did not cover it' % i for i in by_id if i not in seen]
    if bad:
        print('the mutation stamp on %s does not hold (%d problem(s)):' % (sha, len(bad)))
        for b in bad[:20]: print('  ' + b)
        if len(bad) > 20: print('  … and %d more' % (len(bad) - 20))
        return 1
    line = summary
    if stale:
        line += (' — %d expected survivor(s) now killed (%s): update their expect (#133)'
                 % (len(stale), ', '.join(sorted(stale))))
    if unsure:
        line += (' — %d expected survivor(s) killed only by an abort or a timeout (%s): run'
                 ' each alone and read its log before changing its expect'
                 % (len(unsure), ', '.join(sorted(unsure))))
    print(line)
    return 0


def main(argv):
    _check_data()
    by_id = {m['id']: m for m in M}
    cmd = argv[1] if len(argv) > 1 else ''
    if cmd == 'list':
        sel = argv[2:] or [m['id'] for m in M]
        unknown = [i for i in sel if i not in by_id]
        if unknown:
            print('no such mutant: ' + ' '.join(unknown), file=sys.stderr); return 2
        for i in sel:
            m = by_id[i]
            print('\t'.join([i, m['file'], ' '.join(SUITES[s] for s in m['suites']), m['expect']]))
        return 0
    if cmd == 'apply' and len(argv) == 4:
        m = by_id.get(argv[2])
        if m is None:
            print('no such mutant: ' + argv[2], file=sys.stderr); return 2
        p = os.path.join(argv[3], m['file'])
        t = _read(p)
        n = t.count(m['old'])
        if n != 1:
            print('%s: its old text occurs %d times in %s, not once' % (m['id'], n, m['file']), file=sys.stderr); return 3
        with open(p, 'w', encoding='utf-8', newline='') as f:
            f.write(t.replace(m['old'], m['new'], 1))
        return 0
    if cmd == 'verify' and len(argv) == 4:
        return verify(argv[2], argv[3], by_id)
    if cmd == 'check' and len(argv) == 3:
        bad = 0
        for m in M:
            n = _read(os.path.join(argv[2], m['file'])).count(m['old'])
            if n != 1:
                bad += 1; print('%s: its old text occurs %d times in %s, not once' % (m['id'], n, m['file']))
        print('%d mutants, %d not anchored' % (len(M), bad))
        return 1 if bad else 0
    print(__doc__, file=sys.stderr)
    return 2


if __name__ == '__main__':
    sys.exit(main(sys.argv))
